import * as THREE from './assets/three.module.js';
import {findTarget} from './combat.mjs';
const point=(data,progress,offset,height=1.65)=>{const s=data.sample(progress/data.length);return s.p.addScaledVector(s.side,offset).add(new THREE.Vector3(0,height,0));};
export function createCombatVisuals(scene){const pool=[];for(let i=0;i<5;i++){const line=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,1,6),new THREE.MeshBasicMaterial({color:0xffedab}));scene.add(line);line.visible=false;const hit=new THREE.Mesh(new THREE.SphereGeometry(.3,10,8),new THREE.MeshBasicMaterial({color:0xffcf69,wireframe:true}));scene.add(hit);hit.visible=false;pool.push({line,hit});}const ring=new THREE.Mesh(new THREE.TorusGeometry(.75,.045,6,32),new THREE.MeshBasicMaterial({color:0xffd68c}));ring.rotation.x=Math.PI/2;scene.add(ring);return {pool,ring};}
export function updateCombatVisuals(visuals,data,race){const target=findTarget(race.player,race.bots,data.length);visuals.ring.visible=!!target&&!race.player.rescue;if(target){const b=race.bots[target.index];visuals.ring.position.copy(point(data,b.progress,b.offset,.1));}for(let i=0;i<visuals.pool.length;i++){const {line,hit}=visuals.pool[i],s=race.projectiles[i];line.visible=!!s&&!s.resolved;hit.visible=!!s&&s.resolved&&s.targetIndex>=0;if(!s)continue;const from=point(data,s.startProgress,s.startOffset),to=point(data,s.endProgress,s.endOffset),u=Math.min(1,s.elapsed/s.travel),a=from.clone().lerp(to,Math.max(0,u-.2)),b=from.clone().lerp(to,u),delta=b.clone().sub(a);line.position.copy(a).add(b).multiplyScalar(.5);line.scale.y=Math.max(.01,delta.length());line.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),delta.normalize());hit.position.copy(to);hit.scale.setScalar(.7+(s.elapsed-s.travel)*6);}}
export function gunSound(audio,volume=1){if(!audio||!volume)return;const {ctx}=audio,t=ctx.currentTime,b=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*.09),ctx.sampleRate),d=b.getChannelData(0);let seed=81;for(let i=0;i<d.length;i++){seed=(seed*1664525+1013904223)>>>0;d[i]=(seed/4294967296*2-1)*Math.exp(-i/d.length*9);}const s=ctx.createBufferSource(),g=ctx.createGain(),f=ctx.createBiquadFilter();s.buffer=b;f.type='highpass';f.frequency.value=650;g.gain.value=volume*.7;s.connect(f);f.connect(g);g.connect(audio.master);s.start(t);s.onended=()=>{s.disconnect();g.disconnect();f.disconnect();};}
